sp_widget.client_script:
api.controller = function() {

    var c = this;


    /* =========================================
       FORM MODEL
       ========================================= */

    c.form = {

        useCase: "",

        mealType: "",

        messHall: "",

        priority: "",

        description: ""

    };


    c.submitting = false;


    /* =========================================
       SUBMIT REQUEST
       ========================================= */

    c.submitRequest = function() {

        if (c.submitting) {

            return;

        }


        /* Client-side validation */

        if (!c.form.useCase ||
            !c.form.mealType ||
            !c.form.messHall ||
            !c.form.priority ||
            !c.form.description) {

            c.data.error =
                "Please fill in all required fields.";

            return;

        }


        c.data.error = "";

        c.submitting = true;


        c.server.get({

            action: "submit_request",

            useCase:
                c.form.useCase,

            mealType:
                c.form.mealType,

            messHall:
                c.form.messHall,

            priority:
                c.form.priority,

            description:
                c.form.description

        }).then(function(response) {

            c.data.success =
                response.data.success;

            c.data.error =
                response.data.error;

            c.data.requestNumber =
                response.data.requestNumber;

            c.submitting = false;


            if (response.data.success) {

                /* Clear form */

                c.form = {

                    useCase: "",

                    mealType: "",

                    messHall: "",

                    priority: "",

                    description: ""

                };

            }

        }, function() {

            c.submitting = false;

            c.data.error =
                "Something went wrong. Please try again.";

        });

    };


    /* =========================================
       BACK TO DASHBOARD
       ========================================= */

    c.backToDashboard = function() {

        window.location.href =
            "?id=cfms_student";

    };


    /* =========================================
       VIEW MY REQUESTS
       ========================================= */

    c.viewRequests = function() {

        window.location.href =
            "?id=cfms_requests";

    };


    /* =========================================
       RAISE ANOTHER
       ========================================= */

    c.raiseAnother = function() {

        c.data.success = false;

        c.data.requestNumber = "";

        c.data.error = "";

    };

};

sp_widget.css:
/* =========================================
   CFMS RAISE FOOD REQUEST
   ========================================= */

.cfms-request-page {
    min-height: 100vh;

    background: #f0fbfc;

    font-family:
        "Segoe UI",
        Tahoma,
        Geneva,
        Verdana,
        sans-serif;

    color: #263238;

    padding-bottom: 50px;
}


/* =========================================
   HEADER
   ========================================= */

.request-header {
    min-height: 105px;

    background: #00acc1;

    color: white;

    display: flex;

    align-items: center;

    padding: 25px 7%;

    box-sizing: border-box;
}


.header-left {
    display: flex;

    align-items: center;

    gap: 18px;
}


.header-left h1 {
    margin: 0 0 5px;

    font-size: 29px;

    font-weight: 700;
}


.header-left p {
    margin: 0;

    font-size: 13px;

    opacity: 0.9;
}


.back-btn {
    width: 42px;
    height: 42px;

    border: 1px solid rgba(255,255,255,0.7);

    background: transparent;

    color: white;

    border-radius: 8px;

    cursor: pointer;

    font-size: 17px;
}


.back-btn:hover {
    background: white;

    color: #00acc1;
}


/* =========================================
   MAIN CONTAINER
   ========================================= */

.request-container {
    max-width: 1100px;

    margin: 35px auto;

    padding: 0 25px;

    box-sizing: border-box;

    display: grid;

    grid-template-columns:
        minmax(0, 1fr)
        300px;

    gap: 25px;

    align-items: start;
}


/* =========================================
   FORM CARD
   ========================================= */

.request-card {
    background: white;

    border-radius: 15px;

    border: 1px solid #e1eff1;

    box-shadow:
        0 5px 20px rgba(0,0,0,0.06);

    padding: 32px;
}


.card-title {
    display: flex;

    align-items: center;

    gap: 15px;

    margin-bottom: 30px;

    padding-bottom: 22px;

    border-bottom: 1px solid #e9f1f2;
}


.title-icon {
    width: 52px;
    height: 52px;

    border-radius: 11px;

    background: #e0f7fa;

    color: #00acc1;

    display: flex;

    align-items: center;

    justify-content: center;

    font-size: 22px;
}


.card-title h2 {
    margin: 0 0 5px;

    color: #263238;

    font-size: 21px;
}


.card-title p {
    margin: 0;

    color: #78909c;

    font-size: 13px;
}


/* =========================================
   FORM
   ========================================= */

.form-group {
    margin-bottom: 22px;
}


.form-group label {
    display: block;

    margin-bottom: 8px;

    color: #37474f;

    font-size: 14px;

    font-weight: 600;
}


.required {
    color: #e53935;
}


.form-control {
    width: 100%;

    min-height: 44px;

    box-sizing: border-box;

    padding: 10px 13px;

    border: 1px solid #cfdfe2;

    border-radius: 7px;

    background: white;

    color: #263238;

    font-family: inherit;

    font-size: 14px;

    outline: none;

    transition: 0.2s ease;
}


.form-control:focus {
    border-color: #00acc1;

    box-shadow:
        0 0 0 3px rgba(0,172,193,0.10);
}


select.form-control {
    cursor: pointer;
}


.description-box {
    resize: vertical;

    min-height: 135px;

    line-height: 1.6;
}


.character-help {
    margin-top: 6px;

    color: #90a4ae;

    font-size: 11px;
}


/* =========================================
   STUDENT DISPLAY
   ========================================= */

.student-display {
    display: flex;

    align-items: center;

    gap: 12px;

    padding: 12px;

    border-radius: 8px;

    background: #f0fbfc;

    border: 1px solid #d9eef0;
}


.student-icon {
    width: 40px;
    height: 40px;

    border-radius: 50%;

    background: #e0f7fa;

    color: #00acc1;

    display: flex;

    align-items: center;

    justify-content: center;
}


.student-display strong {
    display: block;

    color: #263238;

    font-size: 14px;
}


.student-display span {
    display: block;

    margin-top: 2px;

    color: #78909c;

    font-size: 12px;
}


/* =========================================
   FORM BUTTONS
   ========================================= */

.form-actions {
    display: flex;

    justify-content: flex-end;

    gap: 12px;

    padding-top: 10px;

    border-top: 1px solid #edf3f4;
}


.cancel-btn {
    padding: 11px 22px;

    border: 1px solid #cfdfe2;

    background: white;

    color: #546e7a;

    border-radius: 7px;

    font-size: 14px;

    font-weight: 600;

    cursor: pointer;
}


.cancel-btn:hover {
    background: #f5fafa;
}


.submit-btn {
    padding: 11px 24px;

    border: none;

    background: #00acc1;

    color: white;

    border-radius: 7px;

    font-size: 14px;

    font-weight: 600;

    cursor: pointer;

    transition: 0.2s ease;
}


.submit-btn:hover {
    background: #008fa1;

    transform: translateY(-1px);
}


.submit-btn:disabled {
    opacity: 0.7;

    cursor: not-allowed;

    transform: none;
}


/* =========================================
   INFORMATION CARD
   ========================================= */

.request-info-card {
    background: #4dd0e1;

    border-radius: 15px;

    padding: 27px;

    color: #263238;

    box-sizing: border-box;
}


.info-icon {
    width: 45px;
    height: 45px;

    border-radius: 50%;

    background: white;

    color: #00acc1;

    display: flex;

    align-items: center;

    justify-content: center;

    font-size: 20px;

    margin-bottom: 15px;
}


.request-info-card h3 {
    margin: 0 0 18px;

    font-size: 19px;
}


.request-info-card ul {
    margin: 0;

    padding-left: 20px;
}


.request-info-card li {
    margin-bottom: 13px;

    color: #37474f;

    font-size: 13px;

    line-height: 1.5;
}


/* =========================================
   SUCCESS MESSAGE
   ========================================= */

.success-message {
    display: flex;

    align-items: center;

    gap: 15px;

    padding: 18px;

    margin-bottom: 25px;

    border-radius: 9px;

    background: #e8f5e9;

    border: 1px solid #c8e6c9;

    color: #2e7d32;
}


.success-icon {
    width: 42px;
    height: 42px;

    border-radius: 50%;

    background: #43a047;

    color: white;

    display: flex;

    align-items: center;

    justify-content: center;
}


.success-message h3 {
    margin: 0 0 4px;

    font-size: 16px;
}


.success-message p {
    margin: 0;

    font-size: 13px;
}


/* =========================================
   ERROR MESSAGE
   ========================================= */

.error-message {
    display: flex;

    align-items: center;

    gap: 10px;

    padding: 13px 15px;

    margin-bottom: 20px;

    border-radius: 7px;

    background: #ffebee;

    border: 1px solid #ffcdd2;

    color: #c62828;

    font-size: 13px;
}


/* =========================================
   SUCCESS BUTTONS
   ========================================= */

.after-success {
    display: flex;

    justify-content: center;

    gap: 12px;

    margin-top: 20px;
}


.primary-btn {
    padding: 11px 20px;

    border: none;

    border-radius: 7px;

    background: #00acc1;

    color: white;

    font-weight: 600;

    cursor: pointer;
}


.secondary-btn {
    padding: 11px 20px;

    border: 1px solid #00acc1;

    border-radius: 7px;

    background: white;

    color: #00acc1;

    font-weight: 600;

    cursor: pointer;
}


/* =========================================
   RESPONSIVE
   ========================================= */

@media (max-width: 850px) {

    .request-container {
        grid-template-columns: 1fr;
    }

}


@media (max-width: 600px) {

    .request-header {
        padding: 22px 20px;
    }

    .header-left h1 {
        font-size: 23px;
    }

    .request-container {
        margin: 20px auto;

        padding: 0 15px;
    }

    .request-card {
        padding: 22px;
    }

    .form-actions {
        flex-direction: column-reverse;
    }

    .cancel-btn,
    .submit-btn {
        width: 100%;
    }

    .after-success {
        flex-direction: column;
    }

    .primary-btn,
    .secondary-btn {
        width: 100%;
    }

}

sp_widget.script:
(function() {

    /* =========================================
       DEFAULT DATA
       ========================================= */

    data.success = false;

    data.error = "";

    data.requestNumber = "";

    data.userName = gs.getUserDisplayName();

    data.userEmail = gs.getUser().getEmail();


    /* =========================================
       LOGIN CHECK
       ========================================= */

    if (!gs.isLoggedIn()) {

        data.error = "Please login before raising a request.";

        return;
    }


    /* =========================================
       ROLE CHECK
       ========================================= */

    if (!gs.hasRole("cfms_student") &&
        !gs.hasRole("admin")) {

        data.error =
            "You are not authorized to raise a food request.";

        return;
    }


    /* =========================================
       SUBMIT REQUEST
       ========================================= */

    if (input &&
        input.action == "submit_request") {

        var useCase =
            input.useCase || "";

        var mealType =
            input.mealType || "";

        var messHall =
            input.messHall || "";

        var priority =
            input.priority || "3";

        var description =
            input.description || "";


        /* -------------------------------------
           VALIDATION
           ------------------------------------- */

        if (!useCase ||
            !mealType ||
            !messHall ||
            !priority ||
            !description) {

            data.error =
                "Please fill in all required fields.";

            return;
        }


        /* -------------------------------------
           CREATE INCIDENT
           ------------------------------------- */

        var incident =
            new GlideRecord("incident");

        incident.initialize();


        /* Student */

        incident.setValue(
            "caller_id",
            gs.getUserID()
        );


        /* Short description */

        incident.setValue(
            "short_description",
            "CFMS - " +
            useCase +
            " - " +
            mealType
        );


        /* Description */

        var fullDescription =
            "CFMS FOOD REQUEST\n\n" +

            "Request Type: " +
            useCase +

            "\nMeal Type: " +
            mealType +

            "\nMess Hall: " +
            messHall +

            "\n\nStudent: " +
            gs.getUserDisplayName() +

            "\nEmail: " +
            gs.getUser().getEmail() +

            "\n\nDescription:\n" +
            description;


        incident.setValue(
            "description",
            fullDescription
        );


        /* -------------------------------------
           PRIORITY
           ------------------------------------- */

        incident.setValue(
            "priority",
            priority
        );


        /* -------------------------------------
           OPTIONAL CFMS CUSTOM FIELDS

           If you create these fields later,
           the script will automatically use them.
           ------------------------------------- */

        if (incident.isValidField("u_cfms_use_case")) {

            incident.setValue(
                "u_cfms_use_case",
                useCase
            );

        }


        if (incident.isValidField("u_cfms_meal_type")) {

            incident.setValue(
                "u_cfms_meal_type",
                mealType
            );

        }


        if (incident.isValidField("u_cfms_mess_hall")) {

            incident.setValue(
                "u_cfms_mess_hall",
                messHall
            );

        }


        /* -------------------------------------
           ASSIGNMENT GROUP

           Critical → Hostel Management Group
           High     → Hostel Admin Group
           Medium   → Mess Staff Group
           Low      → Mess Staff Group
           ------------------------------------- */

        var groupName = "";


        if (priority == "1") {

            groupName =
                "Hostel Management Group";

        }

        else if (priority == "2") {

            groupName =
                "Hostel Admin Group";

        }

        else {

            groupName =
                "Mess Staff Group";

        }


        /* Find assignment group */

        var groupGR =
            new GlideRecord("sys_user_group");

        groupGR.addQuery(
            "name",
            groupName
        );

        groupGR.setLimit(1);

        groupGR.query();


        if (groupGR.next()) {

            incident.setValue(
                "assignment_group",
                groupGR.getUniqueValue()
            );

        }


        /* -------------------------------------
           INSERT
           ------------------------------------- */

        var newSysId =
            incident.insert();


        if (!newSysId) {

            data.error =
                "Unable to create the request. Please try again.";

            return;
        }


        /* -------------------------------------
           SUCCESS
           ------------------------------------- */

        data.success = true;

        data.requestNumber =
            incident.getValue("number");

    }

})();
